from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'english','best-friends','Best Friends',
 ('Four shapes and a wise star','Circle, Square, Triangle and Rectangle are friends, but one day each claims to be the best. They ask a wise star to decide. She tells them that together they can make the most beautiful pictures and patterns. This chapter is about shapes, friendship and the small words a and an.'),
 [('The four friends and their quarrel',['Four friends, Circle, Square, Triangle and Rectangle, begin to fight about who is the best.','Circle says she is round and beautiful with no sharp edges, and children use her to draw a smiling face.','Square says he has four equal sides, and many sweets are square.','Triangle says she has three sides, and children use her to draw mountains.','Rectangle says he has four sides, two long and two short, and many biscuits and chocolates are rectangles.']),
  ('The star helps',['The friends cannot decide, so they agree to ask the first person they meet. They meet a star.','The wise star says they are all friends and should not fight.','She tells them that together they can create the most beautiful pictures and patterns.','The friends realise their mistake, promise never to fight again and remain best friends forever.','The lesson is that everyone is special in their own way, and we do more wonderful things together than alone.']),
  ('A shape has its own features',['A circle is round and has no sharp edges or corners.','A square has four sides that are all equal.','A triangle has three sides.','A rectangle has four sides, with two equal long sides and two equal short sides.','Look around you: a wheel is a circle, a window can be a rectangle, a roof can be a triangle and a tile can be a square.']),
  ('Using a and an',['We use a before a singular noun that begins with a consonant sound, such as a dog, a cow and a sparrow.','We use an before a singular noun that begins with a vowel sound, which means a, e, i, o or u, such as an eagle, an umbrella and an ice-cream.','The vowels are a, e, i, o and u. All the other letters are consonants.','So we say a brown hen laid an egg.']),
  ('Writing about a friend',['To write about a friend, tell the name, whether a boy or a girl, the age, the favourite colour, the game the friend likes and what the friend wants to become.','A good friend helps us, shares with us and does not fight over small things.'])],
 [('Fill in a or an: ___ eagle sat on ___ building.',[('Eagle begins with the vowel e.','So we use an.'),('Building begins with the consonant b.','So we use a.'),('An eagle sat on a building.','This is correct.')]),
  ('Fill in a or an: ___ apricot and ___ chikoo.',[('Apricot begins with the vowel a.','So we use an.'),('Chikoo begins with the consonant c.','So we use a.'),('An apricot and a chikoo.','This is correct.')])],
 ('Say what the star taught the shapes.',['They are all friends','No need to fight','Together they make patterns','Everyone is special'],['One shape is truly the best','The star chose the circle']),
 ['Circle, Square, Triangle and Rectangle each thought they were best.','Together the shapes make beautiful pictures and patterns.','A circle has no corners, a square has four equal sides, a triangle has three sides.','Use a before consonant sounds and an before vowel sounds.','Friends should not fight; together they do wonders.'],
 [M('1',1,'Who helped the shapes end their fight?','A star',[('The moon','It was a star'),('A bird','It was a star')],'A wise star helped them.'),
  M('2',1,'How many sides does a triangle have?','Three',[('Four','A rectangle has four'),('Two','A triangle has three')],'A triangle has three sides.'),
  M('3',1,'Which shape has no sharp edges?','Circle',[('Square','A square has corners'),('Triangle','A triangle has corners')],'A circle is round.'),
  M('4',1,'Which word goes in the blank: ___ umbrella?','an',[('a','Umbrella begins with a vowel sound'),('the','Not the lesson rule')],'Umbrella begins with u, so we use an.'),
  F('5',2,'The friends decided who was the best.',False,'They could not decide, so they asked the star.'),
  M('6',2,'What lesson did the friends learn?','Together they can create wonders',[('Fighting is fun','They stopped fighting'),('One shape is the best','The star said they are all friends')],'They learned to work together.'),
  M('7',2,'Which is correct?','a dog',[('an dog','Dog begins with a consonant'),('an cow','Cow begins with a consonant')],'Dog begins with d, a consonant, so we use a.'),
  M('8',2,'Which is correct?','an egg',[('a egg','Egg begins with a vowel'),('a eagle','Eagle begins with a vowel')],'Egg begins with e, a vowel, so we use an.'),
  F('9',2,'A square has four equal sides.',True,'All four sides of a square are equal.'),
  M('10',2,'A rectangle has','Two long and two short sides',[('Three equal sides','That is a triangle'),('No sides','That is a circle')],'A rectangle has two long and two short sides.'),
  S('11',3,'Which letters are the vowels? Write them.',['a e i o u','a, e, i, o, u','aeiou'],'The vowels are a, e, i, o and u.'),
  M('12',3,'Which fills the blanks: Maya bought ___ umbrella and ___ pen?','an, a',[('a, an','Umbrella needs an and pen needs a'),('an, an','Pen begins with a consonant')],'Umbrella takes an and pen takes a.')],
 keep=['circle','square','triangle','rectangle'])
